from typing import List


def get_patch_sequence(patch: str, designerWords: str) -> List[int]:
    p, n = len(patch), len(designerWords)
    if p > n:
        return [-1]
    cur = list(designerWords)
    erased = 0
    order = []  # 逆向“揭掉”补丁的顺序

    def removable(i):
        # 窗口内每个位置要么已被揭成 '?'，要么和补丁一致，且至少有一个还没揭
        has_real = False
        for k in range(p):
            c = cur[i + k]
            if c == '?':
                continue
            if c != patch[k]:
                return False
            has_real = True
        return has_real

    progress = True
    while progress and erased < n:
        progress = False
        for i in range(n - p + 1):
            if removable(i):
                for k in range(p):
                    if cur[i + k] != '?':
                        cur[i + k] = '?'
                        erased += 1
                order.append(i)
                progress = True
    if erased < n:
        return [-1]
    return order[::-1]  # 最后揭掉的，就是最先贴上的


def _apply(patch, n, seq):
    s = ['?'] * n
    for i in seq:
        s[i:i + len(patch)] = patch
    return ''.join(s)


if __name__ == "__main__":
    assert get_patch_sequence("ab", "aab") == [0, 1]
    assert get_patch_sequence("yz", "yzzz") == [2, 1, 0]
    assert get_patch_sequence("ab", "ba") == [-1]
    for patch, w in [("abc", "ababcbc"), ("aba", "ababa"), ("xy", "xyxy")]:
        seq = get_patch_sequence(patch, w)
        assert _apply(patch, len(w), seq) == w, (patch, w, seq)
    print("ok")
